UPDATE COMTNENTRPRSMBER 
SET 
       ENTRPRS_MBER_PASSWORD   =  #{entrprsMberPassword}
     , CHG_PWD_LAST_PNTTM = SYSDATETIME
WHERE  ESNTL_ID  = #{uniqId}

mapper.select:
SELECT * FROM ( SELECT ROWNUM AS RN, T.* FROM ( SELECT INSTT_NM AS CMPNY_NM, BIZRNO AS BIZRNO, REPRSNT_NM AS CXFC, INSTT_STTUS AS JOIN_STAT FROM COMTNINSTTINFO I WHERE (#{keyword} = '' OR INSTT_NM LIKE '%' || #{keyword} || '%' OR BIZRNO LIKE '%' || #{keyword} || '%')
AND INSTT_STTUS = #{status}
AND INSTT_STTUS IN ('P', 'A')
ORDER BY INSTT_NM ASC ) T ) Z WHERE Z.RN BETWEEN #{offset} + 1 AND #{offset} + #{pageSize}

SELECT COUNT(1) FROM COMTNINSTTINFO WHERE (#{keyword} = '' OR INSTT_NM LIKE '%' || #{keyword} || '%' OR BIZRNO LIKE '%' || #{keyword} || '%')
AND INSTT_STTUS = #{status}
AND INSTT_STTUS IN ('P', 'A')

SELECT * FROM ( SELECT rownum rn, TB.* FROM ( SELECT ESNTL_ID as UNIQ_ID, 'USR02' as USER_TY, ENTRPRS_MBER_ID as USER_ID, CMPNY_NM as CMPNY_NM, APPLCNT_NM as USER_NM, APPLCNT_EMAIL_ADRES as EMAIL_ADRES, AREA_NO as AREA_NO, ENTRPRS_MIDDLE_TELNO as MIDDLE_TELNO, ENTRPRS_END_TELNO as END_TELNO, '' as MOBLPHON_NO, GROUP_ID as GROUP_ID, ENTRPRS_MBER_STTUS as STTUS, SBSCRB_DE as SBSCRB_DE, BIZ_REG_FILE_PATH as BIZ_REG_FILE_PATH FROM COMTNENTRPRSMBER WHERE 1=1
AND ENTRPRS_MBER_STTUS LIKE #{sbscrbSttus}
AND ENTRPRS_MBER_ID LIKE '%' || #{searchKeyword} || '%'
AND APPLCNT_NM LIKE '%' ||#{searchKeyword}|| '%'
ORDER BY 13 DESC ) TB ) Z WHERE rn BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage}


SELECT COUNT(1) totcnt
FROM    COMVNUSERMASTER
WHERE   USER_ID = #{checkId}


SELECT COUNT(1) totcnt
FROM    COMVNUSERMASTER
WHERE   USER_EMAIL_ADRES = #{checkEmail}

SELECT (
    SELECT COUNT(1) FROM COMTNINSTTINFO WHERE INSTT_NM = #{checkNm}
) + (
    SELECT COUNT(1) FROM COMTNENTRPRSMBER WHERE CMPNY_NM = #{checkNm}
) as totcnt
